{
 "title": "Rundll32 Execution With Uncommon DLL Extension",
 "description": "Detects rundll32 execution where the command line does not contain common DLL extensions (.dll, .drv, .ocx, .cpl), indicating possible stealthy loading of non-standard DLLs.",
 "tags": [
  "attack.stealth",
  "attack.t1218.011"
 ],
 "logsource_category": "process_creation",
 "groups": [
  {
   "name": "selection",
   "fields": [
    {
     "field": "Image",
     "modifier": "endswith",
     "values": [
      "\\\\rundll32.exe"
     ]
    }
   ]
  },
  {
   "name": "filter",
   "fields": [
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      ".dll",
      ".drv",
      ".ocx",
      ".cpl"
     ]
    }
   ]
  },
  {
   "name": "hasargs",
   "fields": [
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      " "
     ]
    }
   ]
  },
  {
   "name": "condition",
   "fields": []
  }
 ],
 "condition": "selection and not filter and hasargs",
 "falsepositives": [
  "Legitimate rundll32 usage with uncommon extensions"
 ],
 "level": "high"
}

