{
 "title": "Suspicious Kernel Dump Using Dtrace",
 "description": "Detects usage of dtrace.exe with command line arguments commonly used to dump kernel memory on Windows systems.",
 "tags": [
  "attack.discovery",
  "attack.t1082"
 ],
 "logsource_category": "process_creation",
 "groups": [
  {
   "name": "selection",
   "fields": [
    {
     "field": "Image|endswith",
     "modifier": "endswith",
     "values": [
      "\\\\dtrace.exe"
     ]
    },
    {
     "field": "CommandLine|contains",
     "modifier": "contains",
     "values": [
      "-w"
     ]
    },
    {
     "field": "CommandLine|contains",
     "modifier": "contains",
     "values": [
      "-o"
     ]
    }
   ]
  }
 ],
 "condition": "selection",
