{
 "title": "DisableRestrictedAdmin Registry Value Tampering",
 "description": "Detects changes to the DisableRestrictedAdmin registry value to enable or disable RestrictedAdmin mode.",
 "tags": [
  "attack.persistence",
  "attack.defense-impairment",
  "attack.t1112"
 ],
 "logsource_category": "registry_set",
 "groups": [
  {
   "name": "selection",
   "fields": [
    {
     "field": "TargetObject|contains",
     "modifier": "contains",
     "values": [
      "\\\\Lsa\\\\DisableRestrictedAdmin"
     ]
    },
    {
     "field": "Details",
     "modifier": "exact",
     "values": [
      "0x00000000",
      "0x00000001",
      "0",
      "1"
     ]
    }
   ]
  },
  {
   "name": "selection_sysmon",
   "fields": [
    {
     "field": "CommandLine|contains",
     "modifier": "contains",
     "values": [
      "DisableRestrictedAdmin"
     ]
    },
    {
     "field": "CommandLine|contains",
     "modifier": "contains",
     "values": [
      "/d 0",
      "/d 1"
     ]
    }
   ]
  }
 ],
 "condition": "selection or selection_sysmon",
 "falsepositives": [
  "Legitimate administrative changes to RestrictedAdmin mode"
 ],
 "level": "high"
}

