history.rule_text:
{
 "title": "Potential UAC Bypass via SilentCleanup Task - Windir Environment Variable Modification",
 "description": "Detects setting of the environment variable 'windir' to a non-default value, which attackers abuse to trigger\n  a UAC bypass via the SilentCleanup scheduled task.",
 "tags": [
  "attack.privilege-escalation",
  "attack.t1548.002"
 ],
 "logsource_category": "process_creation",
 "groups": [
  {
   "name": "selection",
   "fields": [
    {
     "field": "EnvironmentVariableName",
     "modifier": "exact",
     "values": [
      "windir"
     ]
    }
   ]
  },
  {
   "name": "filter_default",
   "fields": [
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "%SystemRoot%"
     ]
    }
   ]
  },
  {
   "name": "selection_registry",
   "fields": [
    {
     "field": "EventID",
     "modifier": "exact",
     "values": []
    },
    {
     "field": "TargetObject",
     "modifier": "endswith",
     "values": [
      "\\Environment\\windir"
     ]
    }
   ]
  }
 ],
 "condition": "(selection or selection_registry) and not filter_default",
 "falsepositives": [],
 "level": "high"
}

{
 "title": "Disable Microsoft Defender Firewall via Registry",
 "description": "Detects attempts to disable Microsoft Defender Firewall by modifying the EnableFirewall registry value via reg.exe.",
 "tags": [
  "attack.defense-impairment",
  "attack.t1686.003"
 ],
 "logsource_category": "process_creation",
 "groups": [
  {
   "name": "selection",
   "fields": [
    {
     "field": "Image",
     "modifier": "endswith",
     "values": [
      "\\\\reg.exe"
     ]
    },
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "add"
     ]
    },
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "HKLM\\\\SYSTEM\\\\CurrentControlSet\\\\Services\\\\SharedAccess\\\\Parameters\\\\FirewallPolicy"
     ]
    },
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "EnableFirewall"
     ]
    },
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "0"
     ]
    }
   ]
  }
 ],
 "condition": "selection",
 "falsepositives": [
  "Legitimate administrative scripts that modify firewall settings via reg.exe"
 ],
 "level": "high"
}
